// ===== Garden watering — edit these =====
const RELAY_CMND  = 'cmnd/o2/villa/08/POWER1';   // Tasmota relay that opens the valve / runs the pump
const RELAY_STAT  = 'stat/o2/villa/08/POWER1';   // same relay's status topic
const STATE_TOPIC = 'o2/garden/watering/state';   // the app listens here
const SCHEDULE = [                                // used when Auto is on (24-hour time)
    { time: '06:00', minutes: 15 },
    { time: '18:30', minutes: 10 },
];
const MAX_MINUTES = 120;                          // safety limit for one run
// =========================================

let st = flow.get('water') || { state: 'OFF', until: null, auto: true, lastRun: '' };
const relay = [];
const now = Date.now();
function start(min) {
    min = Math.max(1, Math.min(MAX_MINUTES, Math.round(Number(min) || 10)));
    st.state = 'ON'; st.until = now + min * 60000; relay.push({ topic: RELAY_CMND, payload: 'ON' });
}
function stop() { st.state = 'OFF'; st.until = null; relay.push({ topic: RELAY_CMND, payload: 'OFF' }); }

if (msg.topic === RELAY_STAT) {                       // relay changed (app, button, Tasmota timer…)
    const on = String(msg.payload).toUpperCase() === 'ON';
    if (on && st.state !== 'ON') { st.state = 'ON'; st.until = st.until || now + 30 * 60000; }   // safety stop after 30 min
    if (!on && st.state === 'ON') { st.state = 'OFF'; st.until = null; }
} else if (msg.topic === 'tick') {                    // every 20 s: end of run + schedule
    if (st.state === 'ON' && st.until && now >= st.until) stop();
    if (st.auto) {
        const d = new Date(), hm = String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
        const key = d.toDateString() + ' ' + hm, s = SCHEDULE.find(x => x.time === hm);
        if (s && st.lastRun !== key && st.state !== 'ON') { st.lastRun = key; start(s.minutes); }
    }
} else {                                              // command from the app: {"cmd":"start","minutes":10} | stop | auto | get
    let c = msg.payload;
    if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) { c = { cmd: c }; } }
    if (c.cmd === 'start') start(c.minutes);
    else if (c.cmd === 'stop') stop();
    else if (c.cmd === 'auto') st.auto = !!c.on;
}
flow.set('water', st);
const state = { topic: STATE_TOPIC, retain: true, payload: {
    state: st.state, until: st.until, auto: st.auto,
    schedule: SCHEDULE.map(x => x.time + ' · ' + x.minutes + ' min').join(', '), updated: now } };
return [relay.length ? relay : null, state];
